import math
gcd_val = 303
lcm_val = 1818
pairs = []
for x in range(1, lcm_val + 1):
    if lcm_val % x == 0:
        for y in range(1, lcm_val + 1):
            if lcm_val % y == 0:
                if math.gcd(x, y) == gcd_val and (x * y) // math.gcd(x, y) == lcm_val:
                    pairs.append((x, y))
len(pairs)

